PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS parish_settings(id INTEGER PRIMARY KEY CHECK(id=1),parish_name TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',default_offering_cents INTEGER NOT NULL DEFAULT 1500 CHECK(default_offering_cents>=0),max_intentions_per_mass INTEGER NOT NULL DEFAULT 3 CHECK(max_intentions_per_mass>=1),receipt_paper_size TEXT NOT NULL DEFAULT '58mm' CHECK(receipt_paper_size IN('58mm','80mm')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mass_schedule_rules(id INTEGER PRIMARY KEY AUTOINCREMENT,weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),time TEXT NOT NULL,max_intentions INTEGER CHECK(max_intentions>=1),is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mass_intentions(id INTEGER PRIMARY KEY AUTOINCREMENT,mass_date TEXT NOT NULL,mass_time TEXT NOT NULL,offerer_first_name TEXT,offerer_last_name TEXT,offerer_phone TEXT,intention_text TEXT NOT NULL,remembered_person TEXT,offering_cents INTEGER NOT NULL DEFAULT 0 CHECK(offering_cents>=0),payment_method TEXT,internal_notes TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS receipts(id INTEGER PRIMARY KEY AUTOINCREMENT,receipt_number INTEGER NOT NULL UNIQUE,intention_id INTEGER NOT NULL REFERENCES mass_intentions(id),receipt_date TEXT NOT NULL,amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'valid',cancelled_reason TEXT,printed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id INTEGER,details TEXT,created_at TEXT NOT NULL);
